const allTranslations = { ...translations, tr: turkishTranslations } as const;

export type TranslationKey = keyof typeof translations.fa;

export function t(locale: Locale, key: TranslationKey): string {
  return allTranslations[locale][key] ?? allTranslations.fa[key];
}

export function formatMoney(amount: number, locale: Locale) {
  const languageTag = locale === "fa" ? "fa-IR" : locale === "ar" ? "ar-IQ" : locale === "tr" ? "tr-TR" : "en-US";
  const number = new Intl.NumberFormat(languageTag, { maximumFractionDigits: 0 }).format(Math.round(amount));
  return locale === "en" ? `${number} Toman` : locale === "tr" ? `${number} TL` : `${number} تومان`;
}

export function formatShortDate(date: string, locale: Locale) {
  const languageTag = locale === "fa" ? "fa-IR" : locale === "ar" ? "ar-IQ" : locale === "tr" ? "tr-TR" : "en-US";
  return new Intl.DateTimeFormat(languageTag, { month: "short", day: "numeric" }).format(new Date(date));
}
